export interface TokenInfo {
    accessToken: string;
    refreshToken?: string;
    expiresAt?: number;
    tokenType?: string;
}

export interface TokenRefreshCallback {
    (newToken: string): Promise<void>;
}

export interface TokenConfig {
    refreshIntervalMs?: number;
    earlyRefreshThresholdMs?: number;
    enableAutoRefresh?: boolean;
}

export class TokenManager {
    private readonly _accessToken: string;
    private readonly _refreshToken?: string;
    private readonly _expiresAt?: number;
    private readonly _tokenType?: string;
    private readonly _refreshCallback?: TokenRefreshCallback;
    private readonly _config: Required<TokenConfig>;
    private _isRefreshing = false;
    private _refreshPromise?: Promise<void>;

    public constructor(info: TokenInfo, refreshCallback?: TokenRefreshCallback, config?: TokenConfig) {
        this._accessToken = info.accessToken;
        this._refreshToken = info.refreshToken;
        this._expiresAt = info.expiresAt;
        this._tokenType = info.tokenType || "Bearer";
        this._refreshCallback = refreshCallback;
        this._config = {
            refreshIntervalMs: config?.refreshIntervalMs ?? 5 * 60 * 1000,
            earlyRefreshThresholdMs: config?.earlyRefreshThresholdMs ?? 60 * 1000,
            enableAutoRefresh: config?.enableAutoRefresh ?? true,
        };
    }

    public get accessToken(): string {
        return this._accessToken;
    }

    public get refreshToken(): string | undefined {
        return this._refreshToken;
    }

    public get tokenType(): string {
        return this._tokenType || "Bearer";
    }

    public get expiresAt(): number | undefined {
        return this._expiresAt;
    }

    public get isExpired(): boolean {
        if (!this._expiresAt) {
            return false;
        }
        const bufferTime = this._config.earlyRefreshThresholdMs;
        return Date.now() >= this._expiresAt - bufferTime;
    }

    public get needsRefresh(): boolean {
        if (!this._refreshToken) {
            return false;
        }
        return this.isExpired && this._config.enableAutoRefresh;
    }

    public get canRefresh(): boolean {
        return !!this._refreshToken;
    }

    public get isRefreshing(): boolean {
        return this._isRefreshing;
    }

    public get authorizationHeader(): string {
        return `${this.tokenType} ${this._accessToken}`;
    }

    public async refreshIfNeeded(): Promise<void> {
        if (!this.needsRefresh || !this.canRefresh || this._isRefreshing) {
            return;
        }

        if (this._refreshPromise) {
            return this._refreshPromise;
        }

        this._isRefreshing = true;
        this._refreshPromise = this.executeRefresh();

        try {
            await this._refreshPromise;
        } finally {
            this._isRefreshing = false;
            this._refreshPromise = undefined;
        }
    }

    private async executeRefresh(): Promise<void> {
        if (!this._refreshCallback || !this._refreshToken) {
            return;
        }

        try {
            await this._refreshCallback(this._refreshToken);
        } catch (error) {
            throw new Error(`Token refresh failed: ${error}`);
        }
    }

    public static isTokenExpired(expiresAt?: number, thresholdMs?: number): boolean {
        if (!expiresAt) {
            return false;
        }
        const threshold = thresholdMs ?? 60 * 1000;
        return Date.now() >= expiresAt - threshold;
    }

    public static parseTokenExpiration(expiresIn: number): number {
        return Date.now() + expiresIn * 1000;
    }

    public getTokenInfo(): Omit<TokenInfo, "accessToken" | "refreshToken"> {
        return {
            expiresAt: this._expiresAt,
            tokenType: this._tokenType,
        };
    }

    public clone(refreshCallback?: TokenRefreshCallback): TokenManager {
        return new TokenManager(
            {
                accessToken: this._accessToken,
                refreshToken: this._refreshToken,
                expiresAt: this._expiresAt,
                tokenType: this._tokenType,
            },
            refreshCallback ?? this._refreshCallback,
            this._config,
        );
    }
}

export function createAuthHeaders(tokenManager: TokenManager): Headers {
    const headers = new Headers();
    headers.set("Authorization", tokenManager.authorizationHeader);
    return headers;
}

export function parseTokenFromResponse(response: {
    access_token?: string;
    expires_in?: number;
    token_type?: string;
}): TokenInfo {
    return {
        accessToken: response.access_token || "",
        expiresAt: response.expires_in ? TokenManager.parseTokenExpiration(response.expires_in) : undefined,
        tokenType: response.token_type,
    };
}
